"""Build a source-linked research ledger; no model benchmark is executed."""
import datetime,hashlib,json,pathlib,re
R=pathlib.Path(__file__).resolve().parent
M=json.loads((R/'source-manifest.json').read_text()); by={s['id']:s for s in M}
claims=[]
def add(id,claim,refs,status='FACT',provenance='1P',boundary='',benchmark=None):
 evidence=[]
 for key,needle in refs:
  s=by[key]; text=(R/s['text_path']).read_text(); lines=text.splitlines()
  found=[i+1 for i,l in enumerate(lines) if needle.casefold() in l.casefold()]
  if not found: raise ValueError((id,key,needle))
  line=found[-1] if key.endswith('_paper') else found[0]
  evidence.append({'source_id':key,'url':s['url'],'raw_sha256':s['sha256'],'text_path':s['text_path'],'line':line,'quote':lines[line-1][:1100]})
 c={'id':id,'claim':claim,'provenance':provenance,'epistemic_status':status,'measurement_status':'ANALYTICAL' if status=='DERIVED' else 'UNMEASURED','verification':'SOURCE_VERIFIED_NOT_LOCALLY_REPRODUCED' if status=='FACT' else status,'boundary':boundary,'evidence':evidence}
 if benchmark:c['benchmark']=benchmark;c['verification']='SOURCE_REPORTED_BENCHMARK_NOT_REPRODUCED'
 claims.append(c)
add('D01','DDPM learns a reverse Gaussian corruption chain; the simplified noise-prediction loss is a weighted denoising-score-matching formulation.', [('ddpm','Simplified training objective'),('score_sde','implicitly computes')])
add('D02','The score is the gradient of log density of the perturbed data. The reverse SDE and associated probability-flow ODE are related samplers, not identical sample paths.', [('score_sde','reverse-time SDE'),('score_sde','probability flow ordinary differential')],boundary='Equality of marginals in the ideal formulation does not equate finite-step solver error or trajectories.')
add('D03','Flow matching regresses a vector field for a chosen probability path. Its path family includes diffusion paths but extends beyond them.', [('flow_matching','subsumes existing diffusion paths'),('flow_matching','target vector field')])
add('D04','Rectified flow learns transport using straight interpolants and can iteratively rectify the coupling; one-step quality is not guaranteed for arbitrary learned flows.', [('rectified_flow','recursively applying'),('rectified_flow','least squares')])
add('D05','D3PM constructs categorical corruption processes, including uniform and absorbing transitions. Masked diffusion is a specialization, not every discrete diffusion model.', [('d3pm','Choice of Markov transition'),('d3pm','absorbing state')])
add('D06','MDLM uses a masked diffusion formulation with carry-over unmasking; its likelihood objective must not be identified with generic fixed-rate masked-language modeling.', [('mdlm','Carry-Over Unmasking'),('mdlm','Continuous-Time Likelihood Bounds')])
add('D07','LLaDA trains a non-causal Transformer on random mask rates with inverse-rate-weighted masked-token cross entropy. SFT leaves prompt tokens clean and masks the response.', [('llada_paper','1t∑'),('llada_paper','does not use a causal mask'),('llada_paper','leave the prompt unchanged')])
add('D08','LLaDA generation fixes a masked output canvas and discretizes reverse time; confidence-based selection is a sampler choice. Its base generate function preserves committed tokens and executes the configured steps.', [('llada_paper','generation length is also treated'),('llada_generate','x0 = torch.where(mask_index, x0, x)'),('llada_generate','for i in range(steps)')],boundary='Remasking provisional predictions is not evidence that every already-committed token is revised. EOS trimming is not equivalent to stopping the compute.')
add('D09','Dream-v0-Instruct-7B initializes from an autoregressive model and adapts it to diffusion; its inspected sampler repeatedly forwards the full sequence under full attention.', [('dream_paper','AR-based LLM Initialization'),('dream_generate','attention_mask = "full"'),('dream_generate','logits = self(x, attention_mask, tok_idx).logits')],boundary='config use_cache=true is not proof of correct persistent AR KV reuse; max_position_embeddings is not an empirically validated long-context score.')
add('D10','Simultaneous independent marginal sampling can break dependencies between tokens; confidence-based parallel decoding trades quality and model evaluations.', [('fast_dllm_paper','conditional independence assumption'),('fast_dllm_paper','highest confidence to ensure progress')])
add('D11','Bidirectional hidden states can change even when a token ID is unchanged. Fast-dLLM uses approximate prefix/suffix caching, with refresh boundaries and quality tradeoffs.', [('fast_dllm_paper','approximate KV Cache'),('fast_dllm_paper','DualCache')],boundary='Not an exact unchanged-AR-cache invariant, and not a proof that all diffusion caching is impossible.')
add('D12','dKV-Cache delays caching by one step after unmasking and periodically refreshes state; its reuse policies are empirical approximations.', [('dkv_paper','One-step Delayed Caching.'),('dkv_paper','Every N steps')])
add('D13','Block diffusion permits causal reuse across finalized blocks while retaining bidirectional refinement within a block.', [('bd3lm','Block Diffusion Distributions and Model Architectures'),('fast_v2_paper','cached as read-only context')],boundary='Exact reuse across trained causal block boundaries does not make intra-block approximate reuse exact.')
add('D14','Fast-dLLM v2 adapts pretrained autoregressive models to block diffusion and pads requests for batch block decoding; it is not merely the training-free v1 cache switch.', [('fast_v2_paper','adaptation experiments'),('fast_v2_paper','right-pad each sequence')])
add('D15','LLaDA2.1 combines mask-to-token prediction with token-to-token editing; LLaDA2.2 adds keep/substitute/delete/insert within a fixed-length block.', [('llada21_paper','Token-to-Token'),('llada22_report','four operations: keep, substitute, delete, and insert'),('llada22_report','keeping the block length fixed')],boundary='Insert/delete is not an unbounded dynamically resized global canvas.')
add('D16','LLaDA2.2 block routing first admits a bounded expert pool and then selects experts per token; parallel positions can expand expert traffic beyond per-token active-parameter arithmetic.', [('llada22_report','C = 48'),('llada22_config_pinned','"num_experts_per_tok": 8'),('llada22_config_pinned','"num_experts": 256')])
add('D17','Released LLaDA2.2-flash card/config specify 128K context, block size 32 and 100B non-embedding parameters, with a public checkpoint revision.', [('llada22_card_pinned','Total Parameters (Non-Embedding)'),('llada22_config_pinned','"max_position_embeddings": 131072'),('llada22_config_pinned','"block_size": 32')],boundary='128K is a declared capacity, not a local validated context limit. Card says non-embedding; do not silently relabel total inclusive parameters.')
add('D18','DiffusionGemma is an open experimental release dated 2026-06-10. Its card specifies encoder-cached context and block-autoregressive 256-token canvases; uniform-state renoising needs no MASK token.', [('google_diffusiongemma_blog','Jun 10, 2026'),('gemma_card_pinned','Once a canvas is fully denoised'),('sglang_gemma_cookbook','with no mask token')])
add('D19','DiffusionGemma card gives 25.2B total and 3.8B active parameters; config confirms 256 canvas, 30 layers, and 262144 position capacity.', [('gemma_card_pinned','25.2B'),('gemma_card_pinned','3.8B'),('gemma_config_pinned','"canvas_length": 256'),('gemma_config_pinned','"max_position_embeddings": 262144')],boundary='Card introductory text mentions video input while its specification table and inspected SGLang recipe list text/image. Video support is not established by this investigation; no video-generation claim.')
add('D20','DiffusionGemma sampling uses entropy-based acceptance, renoising, previous-logit self-conditioning, and stability/confidence stopping with a configured step cap.', [('sglang_gemma_cookbook','Self-Conditioning'),('gemma_generation','"max_denoising_steps": 48'),('sglang_gemma_cookbook','StableAndConfident')],boundary='Termination criteria are operational checks, not proofs of semantic correctness or global convergence.')
add('D21','Current Mercury documentation lists mercury-3, mercury-2.5 and mercury-2 API identities; Mercury 3 launch is dated 2026-10-19.', [('mercury_docs','"model": "mercury-3"'),('mercury_docs','"model": "mercury-2.5"'),('mercury_docs','"model": "mercury-2"'),('mercury3','Oct 19, 2026')],boundary='Released API offering per vendor records; no authenticated API call, immutable weight revision, architecture/precision/NFE or self-hosting support verified.')
add('D22','Mercury provides ordinary streaming and diffusing=true full-text refinement snapshots, and documents JSON-schema structured outputs.', [('mercury_stream','Each chunk contains the full text'),('mercury_structured','Constrain Mercury 3 chat completions')],boundary='An early draft or overwritten chunk is not an immutable committed-token event. Schema reliability and internal enforcement have not been independently tested.')
add('D23','Gemini Diffusion remains described by its official page as an experimental demo, not an open checkpoint or generally available serving engine.', [('gemini_diffusion','currently available as an experimental demo')])
add('D24','SGLang has explicit diffusion algorithms and FDFO scheduling. At the pinned revision requests can preserve unresolved block state, rather than ordinary one-token lockstep decoding.', [('sglang_dllm_docs','First-Done-First-Out'),('sglang_scheduler','keep partial state and KV'),('sglang_scheduler','real tokens, not the mask block')])
add('D25','LLaDA2.2 has an official eight-NVIDIA-GPU SGLang example using JointThresholdInDel; the inspected algorithm performs greedy editing with finite post-edit and regular-update safeguards.', [('llada22_card_pinned','This example uses eight NVIDIA GPUs'),('sglang_joint_indel','Greedy decode'),('sglang_joint_indel','max_regular_update_steps')],boundary='Eight GPUs is an example, not a proved minimum. Card evaluation temperature=1.0 does not mean this greedy engine uses that stochastic evaluation distribution.')
add('D26','The inspected DiffusionGemma SGLang recipe rejects grammar/logit-bias requests, ignores ordinary temperature/top-k/top-p, and streams committed canvases.', [('sglang_gemma_cookbook','are rejected with a 400'),('sglang_gemma_cookbook','Streaming is block-level')],boundary='Recipe eager/unchunked claims are not a universal invariant: current algorithm source also has a fa4 FULL-prefill-CUDA-graph path. Full runtime configuration needs live testing.')
add('D27','Flash-dLLM has actual upstream Triton fused-cache kernels, selective refresh and self-verification; additional verification work must be counted separately from outer iterations.', [('flash_kernel','import triton'),('flash_dllm_paper','additional verification step'),('flash_readme','selective refresh')],boundary='Paper/code prototype with tested NVIDIA setup, not evidence of generic CPU, Apple, AMD or all-model support. Self-verification is not an unconditional exact-distribution guarantee.')
add('D28','DFlash uses a diffusion draft model with an autoregressive target verifier; this does not turn the target into a full diffusion language model.', [('dflash_paper','lightweight block diffusion model'),('dflash_paper','verified in parallel by the target LLM')])
add('D29','The current manuscript already scopes Chapter 1 to text-tokenized autoregressive models and Chapter 2 to an autoregressive model. Its cache-invariance sentence and broad inference-floor wording deserve local scope reminders, not replacement of the core.', [('llada_paper','does not use a causal mask')],status='DERIVED',boundary='Editorial conclusion from inspected manuscript anchors, listed in research.md and proposed-insertions.md; not a claim that the book explicitly says all LLMs are autoregressive.')
add('D30','The frozen four-family Appendix A cutoff is 2026-08-30 with one separately boxed 2026-09-27 observation. New diffusion release material requires a separate dated addendum.', [('mercury3','Oct 19, 2026')],status='DERIVED',boundary='Book-policy evidence: design/manuscript/chapter-27/chapter-27.md:3-14. Current fetched revisions do not establish August-state source contents even for earlier models.')
add('D31','Published agent evaluations of older LLaDA/Dream variants report tool-format and replanning failures; they do not establish impossibility for LLaDA2.2 or Mercury 3.', [('agent_counterexample','Imprecise tool-call formats'),('agent_counterexample','Retry loops')],provenance='2°',boundary='Primary original evaluation paper, but third-party model evaluation is [2°] under this book taxonomy. Not reproduced here.')
add('D32','The Flexibility Trap reports that arbitrary-order decoding can hurt exploration in the evaluated reasoning models; order flexibility and parallelism are distinct axes.', [('order_counterexample','bypass high-uncertainty tokens'),('order_counterexample','retaining the parallel decoding')],provenance='2°',boundary='Bounded empirical counterexample, not theorem that causal order always wins. No numerical benchmark is adopted.')
# Fully qualified benchmark claim records. Missing conditions are explicitly UNVERIFIED.
unknown='UNVERIFIED'
base={'model_revision':unknown,'hardware':unknown,'precision':unknown,'input_length':unknown,'output_length':unknown,'denoising_schedule':unknown,'NFE':unknown,'batch_size':unknown,'quality_metric':unknown,'baseline':unknown,'publication_date':unknown,'reproduced':False}
def bench(**kwargs):return dict(base,**kwargs)
add('B01','The original LLaDA paper reports task-dependent speed/quality: math can benefit, but MBPP lags its LLaMA3 baseline.', [('llada_paper','1.5 and 1.8 times higher throughput'),('llada_paper','MBPP benchmark, LLaDA 8B Base lags')],benchmark=bench(model='LLaDA 8B Base',model_revision='UNVERIFIED benchmark checkpoint; paper arXiv:2502.09992v3',hardware='single NVIDIA A100 80GB',precision='BF16 for both',input_length='paper task means: GSM8K 894, Math 680, MBPP 628, HumanEval 132 tokens',output_length=256,denoising_schedule='uniform time, low-confidence selection; step sweep in Fig. 5',NFE='UNVERIFIED exact speedup-point steps; must recover per plotted point',batch_size=1,quality_metric='GSM8K/Math task score comparable at cited throughput points; HumanEval comparable at matched throughput, MBPP worse',baseline='LLaMA3 8B Base, with KV cache',publication_date='v1 2025-02-14; inspected v3 2025-10-18',reported_value='1.5x GSM8K, 1.8x Math',service_definition='paper generation throughput, not online p95 SLO goodput'))
add('B02','Google reports DiffusionGemma speed at low batch sizes, while explicitly warning of lower overall quality and diminishing benefit at high QPS.', [('gemma_card_pinned','(H100, FP8)'),('google_diffusiongemma_blog','overall output quality is lower'),('google_diffusiongemma_blog','higher serving costs')],benchmark=bench(model='google/diffusiongemma-26B-A4B-it',model_revision='f7f5b7f5fa82ffc52addd066915886d497f5517b is inspected card/config, benchmark weight revision UNVERIFIED',hardware='single NVIDIA H100; blog separately mentions RTX 5090',precision='FP8 for card H100 claim; blog 4x precision UNVERIFIED',input_length=unknown,output_length='canvas 256; complete benchmark output distribution UNVERIFIED',denoising_schedule='recommended entropy-bound sampler; exact speed-run schedule UNVERIFIED',NFE=unknown,batch_size='low batch; exact size UNVERIFIED',quality_metric='vendor explicitly states lower overall quality than standard Gemma 4; speed claim not matched-quality proof',baseline='standard Gemma 4 per blog; exact speed-run engine/settings UNVERIFIED',publication_date='launch 2026-06-10; card revision inspected this run',reported_value='card >1100 tokens/s (H100 FP8); blog up to 4x',service_definition='vendor per-user generation speed, not online fleet goodput'))
add('B03','Mercury 3 vendor launch reports 1068 tokens/s and 4–8x faster comparisons; public retrieved details are insufficient for a reproducible hardware-matched ranking.', [('mercury3','1,068 tokens per second'),('mercury3','4–8x faster')],benchmark=bench(model='mercury-3',hardware='NVIDIA GPUs only; SKU/count UNVERIFIED',quality_metric='vendor multi-benchmark comparison; exact matched-quality service operating point UNVERIFIED',baseline='vendor names GPT-6 Luna and Claude Haiku 5.5; immutable revisions UNVERIFIED',publication_date='2026-10-19',reported_value='1068 tokens/s; 4–8x vendor comparison',service_definition='vendor speed claim; TTFT boundary, batching, queueing and request length UNVERIFIED'))
add('B04','LLaDA2.2 report claims average BF16 decoding throughput 1.64x Ling-2.6-flash over 11 workloads, with an additional 18.6% average FP8 uplift; this is vendor-reported and incomplete for reproduction.', [('llada22_report','average speedup over Ling-2.6-flash'),('llada22_report','18.6% increase')],benchmark=bench(model='inclusionAI/LLaDA2.2-flash',model_revision='inspected HF 9b78da3f9149f1e239fb6d15f20a326fde574b9f; benchmark revision UNVERIFIED',precision='BF16 both; LLaDA2.2 FP8 additionally reported',input_length='128K declared window; actual workload input distribution UNVERIFIED',output_length=unknown,denoising_schedule='evaluation card block=32 threshold=.5 editing_threshold=0; speed-run equivalence UNVERIFIED',quality_metric='17 task scores separately reported; not a per-operating-point quality/latency frontier',baseline='Ling-2.6-flash, MTP enabled with 4 draft tokens',publication_date='release month 2026-07; exact report publication day UNVERIFIED',reported_value='1.64x across 11 workloads; FP8 +18.6%',service_definition='decoding TPS, no online tail-SLO claim'))
