repo=R.parents[1]
for c in claims:
 if c['id'] in local_evidence:
  c['local_evidence']=[]
  for path,line in local_evidence[c['id']]:
   body=(repo/path).read_bytes(); text=body.decode().splitlines()
   c['local_evidence'].append({'path':path,'line':line,'sha256':hashlib.sha256(body).hexdigest(),'quote':text[line-1]})
out={'schema_version':1,'scope':'diffusion mechanisms and language models, not video-generation survey','retrieved_this_run':True,'generated_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'interpretation':'FACT means the quoted source states the scoped claim, not independent benchmark confirmation. UNVERIFIED fields remain unresolved. Third-party model evaluation uses the book provenance 2° even when read in its original paper.','claims':claims,'sources':M}
(R/'claims.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
